const output = ($input.item.json.output || '').toString().trim();
const jsonMatch = output.match(/\{[\s\S]*?"accion"[\s\S]*?\}/);

const TIME_ZONE = 'Europe/Lisbon';
const DURACION_CITA_MIN = 60;
const DURACIONES_TRATAMIENTO = [
  { patrones: ['revision', 'revision dental', 'revisioa', 'revisao', 'checkup', 'check-up'], minutos: 30 },
  { patrones: ['limpieza', 'limpeza', 'nettoyage', 'cleaning'], minutos: 60 },
  { patrones: ['blanqueamiento', 'branqueamento', 'blanchiment', 'whitening'], minutos: 90 },
  { patrones: ['empaste', 'obturacion', 'plombage', 'filling'], minutos: 45 },
  { patrones: ['ortodoncia', 'ortodontia', 'orthodontie', 'orthodontics'], minutos: 60 }
];

const trigger = $('WhatsApp Trigger').first().json;
const telefono = trigger.messages?.[0]?.from || '';

const normalizarTexto = texto => (texto || '')
  .toString()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const datoVacio = valor => valor === null || valor === undefined || valor.toString().trim() === '';

const duracionTratamiento = tratamiento => {
  const valor = normalizarTexto(tratamiento);
  const encontrado = DURACIONES_TRATAMIENTO.find(item =>
    item.patrones.some(patron => valor.includes(normalizarTexto(patron)))
  );
  return encontrado ? encontrado.minutos : DURACION_CITA_MIN;
};

const responder = texto => [{
  json: {
    accion: 'responder',
    es_reserva: false,
    es_cancelacion: false,
    es_modificacion: false,
    telefono,
    respuesta: texto
  }
}];

const normHora = h => {
  if (h === null || h === undefined || h === '') return '';
  if (typeof h === 'number') {
    let totalMin;
    if (h >= 0 && h < 1) {
      totalMin = Math.round(h * 24 * 60);
    } else {
      const horas = Math.floor(h);
      const minutos = Math.round((h - horas) * 60);
      totalMin = horas * 60 + minutos;
    }
    const hh = Math.floor(totalMin / 60).toString().padStart(2, '0');
    const mm = (totalMin % 60).toString().padStart(2, '0');
    return hh + ':' + mm;
  }

  let v = h.toString().trim().toLowerCase();
  v = v.replace(/\s*(horas|hora|hrs?|h)\s*$/i, '').trim();
  v = v.replace('.', ':');

  const ampm = v.match(/^(\d{1,2})(?::(\d{1,2}))?\s*(am|pm)$/i);
  if (ampm) {
    let hh = parseInt(ampm[1], 10);
    const mm = (ampm[2] || '0').padStart(2, '0');
    if (ampm[3].toLowerCase() === 'pm' && hh < 12) hh += 12;
    if (ampm[3].toLowerCase() === 'am' && hh === 12) hh = 0;
    return hh.toString().padStart(2, '0') + ':' + mm;
  }

  if (/^\d{1,2}$/.test(v)) return v.padStart(2, '0') + ':00';
  if (/^\d{1,2}:\d{1,2}:\d{1,2}$/.test(v)) v = v.split(':').slice(0, 2).join(':');
  if (/^\d{1,2}:\d{1,2}$/.test(v)) {
    const parts = v.split(':');
    return parts[0].padStart(2, '0') + ':' + parts[1].padStart(2, '0');
  }

  return v;
};

const horaEnMinutos = horaStr => {
  const m = (horaStr || '').match(/^(\d{2}):(\d{2})$/);
  if (!m) return null;
  const hh = parseInt(m[1], 10);
  const mm = parseInt(m[2], 10);
  if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;
  return hh * 60 + mm;
};

const sumarMinutos = (horaStr, minutos) => {
  const inicio = horaEnMinutos(horaStr);
  if (inicio === null) return '';
  const total = inicio + minutos;
  const hh = Math.floor(total / 60).toString().padStart(2, '0');
  const mm = (total % 60).toString().padStart(2, '0');
  return hh + ':' + mm;
};

const fechaISOValida = fechaStr => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaStr || '')) return false;
  const parts = fechaStr.split('-').map(Number);
  const d = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
  return d.getUTCFullYear() === parts[0] && d.getUTCMonth() === parts[1] - 1 && d.getUTCDate() === parts[2];
};

const obtenerDiaSemana = fechaStr => {
  if (!fechaISOValida(fechaStr)) return -1;
  const parts = fechaStr.split('-').map(Number);
  return new Date(Date.UTC(parts[0], parts[1] - 1, parts[2])).getUTCDay();
};

const hoyClinica = () => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());
  const get = type => parts.find(p => p.type === type).value;
  return get('year') + '-' + get('month') + '-' + get('day');
};

const validarFechaFutura = fechaStr => fechaISOValida(fechaStr) && fechaStr >= hoyClinica();

const validarHorario = (fechaStr, horaStr, duracionMin = DURACION_CITA_MIN) => {
  const dia = obtenerDiaSemana(fechaStr);
  const inicio = horaEnMinutos(horaStr);
  if (dia === -1 || inicio === null) return false;
  if (dia === 0) return false;
  const apertura = 9 * 60;
  const cierre = dia === 6 ? 14 * 60 : 20 * 60;
  return inicio >= apertura && inicio + duracionMin <= cierre;
};

const horarioDia = fechaStr => {
  const dia = obtenerDiaSemana(fechaStr);
  if (dia === -1 || dia === 0) return null;
  return {
    apertura: '09:00',
    cierre: dia === 6 ? '14:00' : '20:00'
  };
};

const offsetClinica = (fechaStr, horaStr) => {
  const probe = new Date(fechaStr + 'T' + horaStr + ':00Z');
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    hour: '2-digit',
    minute: '2-digit',
    timeZoneName: 'longOffset'
  }).formatToParts(probe);
  const tz = (parts.find(p => p.type === 'timeZoneName') || {}).value || 'GMT+00:00';
  const m = tz.match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/);
  if (!m) return '+00:00';
  return m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00').padStart(2, '0');
};

const isoClinica = (fechaStr, horaStr) => fechaStr + 'T' + horaStr + ':00' + offsetClinica(fechaStr, horaStr);

if (jsonMatch) {
  try {
    const data = JSON.parse(jsonMatch[0]);
    const accion = (data.accion || '').toString().trim();

    if (accion === 'guardar_valoracion') {
      if (data.valoracion === undefined || data.valoracion === null || data.valoracion === '') {
        return responder('Gracias. Para guardar tu valoracion, podrias responder con un numero del 1 al 5?');
      }
      const valoracion = parseInt(data.valoracion, 10);
      if (!Number.isInteger(valoracion) || valoracion < 1 || valoracion > 5) {
        return responder('Gracias. Para guardar tu valoracion, podrias responder con un numero del 1 al 5?');
      }
      const comentario = (data.comentario || data.comentario_valoracion || '').toString().trim();
      return [{
        json: {
          accion: 'guardar_valoracion',
          es_reserva: false,
          es_cancelacion: false,
          es_modificacion: false,
          es_valoracion: true,
          valoracion,
          comentario_valoracion: comentario,
          telefono
        }
      }];
    }

    if (accion === 'consultar_horarios') {
      if (datoVacio(data.fecha)) {
        return responder('Claro. Que dia quieres consultar?');
      }
      const tratamiento = data.tratamiento || 'cita estandar';
      const duracion = duracionTratamiento(tratamiento);
      if (!validarFechaFutura(data.fecha)) {
        return responder('Esa fecha no es valida o ya ha pasado. Podrias indicarme una fecha futura en formato YYYY-MM-DD?');
      }
      const horario = horarioDia(data.fecha);
      if (!horario) {
        return responder('Los domingos la clinica esta cerrada. Que otro dia te vendria bien consultar?');
      }
      return [{
        json: {
          accion: 'consultar_horarios',
          es_reserva: false,
          es_cancelacion: false,
          es_modificacion: false,
          es_consulta_horarios: true,
          fecha: data.fecha,
          tratamiento,
          fecha_inicio_consulta: isoClinica(data.fecha, horario.apertura),
          fecha_fin_consulta: isoClinica(data.fecha, horario.cierre),
          hora_apertura: horario.apertura,
          hora_cierre: horario.cierre,
          timezone: TIME_ZONE,
          duracion_minutos: duracion,
          telefono
        }
      }];
    }

    if (accion === 'reservar') {
      if (!datoVacio(data.fecha) && !validarFechaFutura(data.fecha)) {
        return responder('Esa fecha no es valida o ya ha pasado. Podrias indicarme una fecha futura en formato YYYY-MM-DD?');
      }
      if (datoVacio(data.nombre)) {
        return responder('Para reservar la cita, necesito tu nombre completo. Cual es?');
      }
      if (datoVacio(data.tratamiento)) {
        return responder('Que tratamiento quieres reservar?');
      }
      if (datoVacio(data.fecha)) {
        return responder('Que dia quieres reservar? Puedes indicarlo en formato YYYY-MM-DD.');
      }
      if (datoVacio(data.hora)) {
        return responder('A que hora te vendria bien?');
      }

      const hora = normHora(data.hora);
      const duracion = duracionTratamiento(data.tratamiento);
      if (horaEnMinutos(hora) === null) {
        return responder('Necesito la hora en formato HH:mm. Por ejemplo, 16:00.');
      }
      if (!validarHorario(data.fecha, hora, duracion)) {
        return responder('Lo siento, ese horario no es valido. Nuestro horario es de lunes a viernes de 9:00 a 20:00 y los sabados de 9:00 a 14:00. Los domingos estamos cerrados. Que otra hora te vendria bien?');
      }
      const horaFin = sumarMinutos(hora, duracion);
      return [{
        json: {
          accion: 'reservar',
          es_reserva: true,
          es_cancelacion: false,
          es_modificacion: false,
          nombre: data.nombre,
          tratamiento: data.tratamiento,
          fecha: data.fecha,
          hora,
          fecha_inicio: isoClinica(data.fecha, hora),
          fecha_fin: isoClinica(data.fecha, horaFin),
          timezone: TIME_ZONE,
          duracion_minutos: duracion,
          telefono
        }
      }];
    }

    if (accion === 'cancelar') {
      if (datoVacio(data.nombre)) {
        return responder('Para cancelar la cita, necesito tu nombre completo. Cual es?');
      }
      if (datoVacio(data.fecha)) {
        return responder('Que fecha tiene la cita que quieres cancelar?');
      }
      if (datoVacio(data.hora)) {
        return responder('A que hora era la cita que quieres cancelar?');
      }
      const hora = normHora(data.hora);
      if (!fechaISOValida(data.fecha) || horaEnMinutos(hora) === null) {
        return responder('Necesito la fecha en formato YYYY-MM-DD y la hora en formato HH:mm para poder cancelar la cita.');
      }
      return [{
        json: {
          accion: 'cancelar',
          es_reserva: false,
          es_cancelacion: true,
          es_modificacion: false,
          nombre: data.nombre,
          fecha: data.fecha,
          hora,
          telefono
        }
      }];
    }

    if (accion === 'modificar') {
      if (datoVacio(data.nombre)) {
        return responder('Para modificar la cita, necesito tu nombre completo. Cual es?');
      }
      if (datoVacio(data.fecha_actual)) {
        return responder('Cual es la fecha actual de tu cita?');
      }
      if (datoVacio(data.hora_actual)) {
        return responder('A que hora es tu cita actual?');
      }
      if (datoVacio(data.tratamiento)) {
        return responder('Que tratamiento es la cita?');
      }
      if (datoVacio(data.fecha_nueva)) {
        return responder('A que nueva fecha quieres mover la cita?');
      }
      if (datoVacio(data.hora_nueva)) {
        return responder('A que nueva hora quieres mover la cita?');
      }

      const horaActual = normHora(data.hora_actual);
      const horaNueva = normHora(data.hora_nueva);
      const duracion = duracionTratamiento(data.tratamiento);
      if (!fechaISOValida(data.fecha_actual) || horaEnMinutos(horaActual) === null) {
        return responder('Necesito la fecha y hora actuales en formato YYYY-MM-DD y HH:mm para poder modificar la cita.');
      }
      if (!validarFechaFutura(data.fecha_nueva)) {
        return responder('La nueva fecha solicitada no es valida o ya ha pasado. Podrias indicarme una fecha futura en formato YYYY-MM-DD?');
      }
      if (!validarHorario(data.fecha_nueva, horaNueva, duracion)) {
        return responder('Lo siento, el nuevo horario propuesto no es valido. Nuestro horario es de lunes a viernes de 9:00 a 20:00 y los sabados de 9:00 a 14:00. Los domingos estamos cerrados. Que otra hora te vendria bien?');
      }
      const horaFinNueva = sumarMinutos(horaNueva, duracion);
      return [{
        json: {
          accion: 'modificar',
          es_reserva: false,
          es_cancelacion: false,
          es_modificacion: true,
          nombre: data.nombre,
          tratamiento: data.tratamiento,
          fecha_actual: data.fecha_actual,
          hora_actual: horaActual,
          fecha_nueva: data.fecha_nueva,
          hora_nueva: horaNueva,
          fecha_inicio_nueva: isoClinica(data.fecha_nueva, horaNueva),
          fecha_fin_nueva: isoClinica(data.fecha_nueva, horaFinNueva),
          timezone: TIME_ZONE,
          duracion_minutos: duracion,
          telefono
        }
      }];
    }

    if (accion) {
      return responder('Necesito algun dato mas para ayudarte. Puedes indicarme nombre, tratamiento, fecha y hora?');
    }
  } catch (e) {
    return responder('No he podido interpretar bien la solicitud. Puedes escribirme de nuevo lo que necesitas?');
  }
}

if (/^\s*\{[\s\S]*"accion"[\s\S]*\}\s*$/.test(output)) {
  return responder('Necesito algun dato mas para ayudarte. Puedes indicarme nombre, tratamiento, fecha y hora?');
}

return responder(output || 'No he podido entenderte bien. Puedes reformular tu peticion?');

const eventos = $input.all()
  .map(e => e.json || {})
  .filter(evento => evento.start?.dateTime || evento.start?.date);

const datos = $('Normalizar y enrutar').first().json;
const inicio = new Date(datos.fecha_inicio);
const fin = new Date(datos.fecha_fin);
const ocupado = eventos.some(evento => {
  const eStart = new Date(evento.start?.dateTime || evento.start?.date);
  const eEnd = new Date(evento.end?.dateTime || evento.end?.date);
  return inicio < eEnd && fin > eStart;
});

return [{
  json: {
    ...datos,
    ocupado,
    respuesta: ocupado
      ? 'Ese horario ya esta reservado. Te vendria bien otro dia o una hora diferente?'
      : datos.respuesta
  }
}];

const filas = $input.all();
const reserva = $('Evaluar disponibilidad reserva').first().json;
const normalizarTelefono = v => (v || '').toString().replace(/\D/g, '');
const nombre = (reserva.nombre || '').toLowerCase().trim();
const telefono = normalizarTelefono(reserva.telefono);

const citasConfirmadas = filas.filter(item => {
  const row = item.json || {};
  const eN = (row.nombre || '').toLowerCase().trim();
  const eE = (row.estado || '').toLowerCase().trim();
  const eT = normalizarTelefono(row['Numero de telefono'] || row.telefono || row.phone || '');
  const eventId = row['Event ID'];
  return eN === nombre && eE === 'confirmada' && eT === telefono && !!eventId;
});

return [{
  json: {
    ...reserva,
    tiene_duplicados: citasConfirmadas.length > 0,
    citas_antiguas: citasConfirmadas.map(c => c.json)
  }
}];

const data = $('Preparar reserva y duplicados').first().json;
const citasAntiguas = Array.isArray(data.citas_antiguas) ? data.citas_antiguas : [];
return citasAntiguas
  .filter(cita => !!cita['Event ID'])
  .map(cita => ({
    json: {
      eventId: cita['Event ID'],
      nombre: cita.nombre,
      fecha: cita.fecha,
      hora: cita.hora
    }
  }));

const data = $('Preparar reserva y duplicados').first().json;
return [{
  json: {
    accion: 'reservar',
    nombre: data.nombre,
    tratamiento: data.tratamiento,
    fecha: data.fecha,
    hora: data.hora,
    fecha_inicio: data.fecha_inicio,
    fecha_fin: data.fecha_fin,
    telefono: data.telefono,
    duracion_minutos: data.duracion_minutos
  }
}];

const data = $('Preparar crear reserva').first().json;
const eventId = $('Crear evento reserva').first().json.id;
const fechaES = data.fecha.split('-').reverse().join('/');
const respuesta = 'Perfecto, tu cita para ' + data.tratamiento + ' ha quedado confirmada para el ' + fechaES + ' a las ' + data.hora + '. Te esperamos.';
const emailHtml = [
  '<div style="font-family:Arial,sans-serif;max-width:560px">',
  '<h2 style="color:#1a7f5a;border-bottom:2px solid #1a7f5a;padding-bottom:8px">Nueva cita reservada</h2>',
  '<table style="width:100%;border-collapse:collapse">',
  '<tr><td style="padding:8px;font-weight:bold">Paciente</td><td style="padding:8px">' + data.nombre + '</td></tr>',
  '<tr><td style="padding:8px;font-weight:bold">Tratamiento</td><td style="padding:8px">' + data.tratamiento + '</td></tr>',
  '<tr><td style="padding:8px;font-weight:bold">Fecha</td><td style="padding:8px">' + fechaES + '</td></tr>',
  '<tr><td style="padding:8px;font-weight:bold">Hora</td><td style="padding:8px">' + data.hora + '</td></tr>',
  '</table>',
  '<p style="color:#666;font-size:12px;margin-top:16px">Cita registrada automaticamente por el chatbot.</p>',
  '</div>'
].join('');
return [{
  json: {
    ...data,
    eventId,
    respuesta,
    email_subject: 'Nueva cita: ' + data.nombre + ' - ' + data.tratamiento,
    email_html: emailHtml
  }
}];

const normHora = h => {
  if (h === null || h === undefined || h === '') return '';
  if (typeof h === 'number') {
    const totalMin = h >= 0 && h < 1 ? Math.round(h * 24 * 60) : Math.round(Math.floor(h) * 60 + (h % 1) * 60);
    const hh = Math.floor(totalMin / 60).toString().padStart(2, '0');
    const mm = (totalMin % 60).toString().padStart(2, '0');
    return hh + ':' + mm;
  }
  let v = h.toString().trim().toLowerCase().replace(/\s*(horas|hora|hrs?|h)\s*$/i, '').replace('.', ':').trim();
  if (/^\d{1,2}$/.test(v)) return v.padStart(2, '0') + ':00';
  if (/^\d{1,2}:\d{2}:\d{2}$/.test(v)) v = v.slice(0, 5);
  if (/^\d{1,2}:\d{1,2}$/.test(v)) {
    const parts = v.split(':');
    return parts[0].padStart(2, '0') + ':' + parts[1].padStart(2, '0');
  }
  return v;
};

const normFecha = f => {
  if (!f) return '';
  const v = f.toString().trim();
  const es = v.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (es) return es[3] + '-' + es[2] + '-' + es[1];
  const iso = v.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return iso[1] + '-' + iso[2] + '-' + iso[3];
  return v;
};

const normalizarTelefono = v => (v || '').toString().replace(/\D/g, '');

const datos = $('Normalizar y enrutar').first().json;
const nombre = (datos.nombre || '').toLowerCase().trim();
const fecha = normFecha(datos.fecha || '');
const hora = normHora(datos.hora || '');
const telefono = normalizarTelefono(datos.telefono || '');

const candidatas = $input.all().filter(item => {
  const row = item.json || {};
  const eN = (row.nombre || '').toLowerCase().trim();
  const eF = normFecha(row.fecha || '');
  const eH = normHora(row.hora || '');
  const eE = (row.estado || '').toLowerCase().trim();
  const eventId = row['Event ID'];
  return eN === nombre && eF === fecha && eH === hora && eE === 'confirmada' && !!eventId;
});

const conTelefono = candidatas.filter(item => {
  const row = item.json || {};
  const eT = normalizarTelefono(row['Numero de telefono'] || row.telefono || row.phone || '');
  return eT && eT === telefono;
});

const cita = conTelefono[0] || (candidatas.length === 1 ? candidatas[0] : null);
if (!cita) {
  return [{
    json: {
      ...datos,
      encontrada: false,
      respuesta: 'No he encontrado una cita confirmada con ese nombre, fecha y hora. Revisa los datos o llama a la clinica al 912 345 678.'
    }
  }];
}

return [{
  json: {
    ...datos,
    ...cita.json,
    encontrada: true,
    eventId: cita.json['Event ID'],
    telefono: datos.telefono
  }
}];

const cita = $('Resolver cita cancelacion').first().json;
const fechaES = (cita.fecha || '').split('-').reverse().join('/');
const respuesta = 'Tu cita de ' + (cita.tratamiento || 'tratamiento') + ' del ' + fechaES + ' a las ' + cita.hora + ' ha sido cancelada correctamente. Esperamos verte pronto.';
const emailHtml = [
  '<div style="font-family:Arial,sans-serif;max-width:560px">',
  '<h2 style="color:#d9534f;border-bottom:2px solid #d9534f;padding-bottom:8px">Cita cancelada</h2>',
  '<table style="width:100%;border-collapse:collapse">',
  '<tr><td style="padding:8px;font-weight:bold">Paciente</td><td style="padding:8px">' + cita.nombre + '</td></tr>',
  '<tr><td style="padding:8px;font-weight:bold">Tratamiento</td><td style="padding:8px">' + (cita.tratamiento || '') + '</td></tr>',
  '<tr><td style="padding:8px;font-weight:bold">Fecha</td><td style="padding:8px">' + fechaES + '</td></tr>',
  '<tr><td style="padding:8px;font-weight:bold">Hora</td><td style="padding:8px">' + cita.hora + '</td></tr>',
  '</table>',
  '<p style="color:#666;font-size:12px;margin-top:16px">Cancelacion procesada automaticamente por el chatbot.</p>',
  '</div>'
].join('');
return [{
  json: {
    ...cita,
    respuesta,
    email_subject: 'Cita cancelada: ' + cita.nombre,
